const t0 = Date.now();
const access = $('Проверить доступ').first().json;
const body = $('POST /inbox/classify').first().json.body || {};
const text = String(body.text ?? '').trim();
const TYPES = ['review', 'wholesale', 'blogger', 'candidate', 'approval'];
const exampleId = TYPES.includes(body.exampleId) ? body.exampleId : '';
const count = (name) => $(name).all().filter((i) => i.json && i.json.request_id).length;
const recent = count('Недавние обращения');
const liveToday = count('Живые за сутки');
const chars = [...text].length;
let stage = 'jev';
let reason = '';
if (recent >= 5) stage = 'rate';
else if (chars < 15) { stage = 'reject'; reason = 'too_short'; }
else if (chars > 3000) { stage = 'reject'; reason = 'too_long'; }
else if (!/[\p{L}\p{N}]/u.test(text)) { stage = 'reject'; reason = 'symbols'; }
else if (liveToday >= 150) { if (exampleId) stage = 'recorded'; else { stage = 'reject'; reason = 'daily_limit'; } }
const requestId = 'r' + Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
return [{ json: { stage, reason, text: [...text].slice(0, 3000).join(''), exampleId, requestId, rulesMs: Math.max(1, Date.now() - t0), access, t0: Date.now() } }];

const r = $('Правила').first().json;
const reason = $input.first().json.reason || r.reason || 'ai_unavailable';
const result = { id: r.requestId, outcome: 'rejected', reason, rulesMs: r.rulesMs, flags: [], used: r.access.invite.used, limit: r.access.invite.limit };
return [{ json: { requestId: r.requestId, text: r.text, live: false, outcome: 'rejected', category: '', department: '', result } }];

const r = $('Правила').first().json;
const ex = $input.first().json || {};
let rec = null;
try { rec = JSON.parse(ex.result_json); } catch (e) { rec = null; }
if (!rec) {
  const result = { id: r.requestId, outcome: 'rejected', reason: 'ai_unavailable', rulesMs: r.rulesMs, flags: [], used: r.access.invite.used, limit: r.access.invite.limit };
  return [{ json: { requestId: r.requestId, text: r.text, live: false, outcome: 'rejected', category: '', department: '', result } }];
}
const result = { ...rec, id: r.requestId, rulesMs: r.rulesMs, used: r.access.invite.used, limit: r.access.invite.limit, jev: { ...rec.jev, source: 'recorded' } };
return [{ json: { requestId: r.requestId, text: r.text, live: false, outcome: result.outcome, category: rec.jev.category, department: result.department || '', result } }];

const r = $('Правила').first().json;
const a = $input.first().json.answers || {};
const ms = Date.now() - r.t0;
const p = (q) => (a[q] && typeof a[q].noul === 'number' ? a[q].noul : 0);
const sc = (q) => (a[q] && typeof a[q].score === 'number' ? Math.min(5, Math.max(1, Math.round(a[q].score) + 1)) : undefined);
const category = (a.category && a.category.choice) || 'off_topic';
const pCategory = a.category && typeof a.category.confidence === 'number' ? a.category.confidence : 0;
const TYPES = ['review', 'wholesale', 'blogger', 'candidate', 'approval'];
const DEPT = { review: 'service', wholesale: 'wholesale', blogger: 'marketing', candidate: 'hr', approval: 'approvals' };
const SCORE = { review: 'irritation', wholesale: 'lead_quality', blogger: 'audience_fit', candidate: 'candidate_fit', approval: 'risk' };
// Калибровка: на коротких деловых фразах Jev занижает «это обращение?», но уверенно видит категорию.
const pRequest = TYPES.includes(category) ? Math.max(p('is_request'), pCategory) : p('is_request');
const jev = { pRequest, category, pCategory, pInjection: p('injection'), ms, source: 'live' };
let outcome; let reason; let department = ''; const flags = [];
if (jev.pInjection >= 0.5) { outcome = 'rejected'; reason = 'injection'; }
else if (category === 'spam' && pCategory >= 0.5) { outcome = 'rejected'; reason = 'spam'; department = 'spam'; }
else if (pRequest < 0.4) { outcome = 'rejected'; reason = 'off_topic'; }
else if (pRequest <= 0.7 || pCategory < 0.65 || !TYPES.includes(category)) { outcome = 'manual'; department = 'manual'; }
else { outcome = 'routed'; department = DEPT[category]; }
if (TYPES.includes(category)) jev.score = sc(SCORE[category]);
if (category === 'review') { jev.pCounterfeit = p('counterfeit'); if (outcome === 'routed' && jev.pCounterfeit >= 0.6) flags.push('legal'); }
if (category === 'approval') jev.pEnoughData = p('enough_data');
const used = r.access.invite.used + 1;
const result = { id: r.requestId, outcome, rulesMs: r.rulesMs, jev, flags, used, limit: r.access.invite.limit };
if (reason) result.reason = reason;
if (department) result.department = department;
const limitReached = used >= r.access.invite.limit && !r.access.invite.limitNotified;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: { requestId: r.requestId, text: r.text, live: true, outcome, category, department, result, used, limitReached, limitText: esc(r.access.invite.label) + ': лимит исчерпан' } }];
